<?php
/** Server-rendered presentation for the team archive. */
use yii\helpers\Html;
?>
<?php $this->title = '留言管理'; ?><div class="page-heading compact"><span class="eyebrow">LISTEN & CONNECT</span><h1>留言管理</h1><p>审核后公开留言；回复将与已通过的留言一起展示。</p></div><?php foreach ($rows as $row): ?><article class="panel moderation-card"><div class="card-meta"><strong><?= Html::encode($row['name']) ?> <small class="muted"><?= Html::encode($row['email']) ?></small></strong><span class="badge"><?= Html::encode($row['status']) ?></span></div><p><?= nl2br(Html::encode($row['body'])) ?></p><?php foreach ($row['replies'] ?? [] as $reply): ?><div class="reply"><strong>工坊回复</strong><p><?= nl2br(Html::encode($reply['body'])) ?></p></div><?php endforeach ?><?= Html::beginForm(['/site/moderate','id'=>$row['id']],'post') ?><div class="moderation-fields"><div><label for="status-<?= (int)$row['id'] ?>">审核状态</label><?= Html::dropDownList('status',$row['status'],['pending'=>'待审核','approved'=>'通过并公开','rejected'=>'不予公开'],['id'=>'status-'.(int)$row['id']]) ?></div><div><label for="reply-<?= (int)$row['id'] ?>">回复内容（可选）</label><?= Html::textarea('reply','',['id'=>'reply-'.(int)$row['id'],'rows'=>3,'maxlength'=>2000]) ?></div></div><?= Html::submitButton('保存审核 / 回复',['class'=>'button secondary']) ?><?= Html::endForm() ?></article><?php endforeach ?><?php if (!$rows): ?><p class="empty-state">暂无待处理留言。</p><?php endif ?>
